// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/// @title Solvency harness: totalAssets >= totalShares under fee + rounding
/// @notice Proves that after a deposit with fee and floor-division share minting,
///         the vault's asset-to-share ratio never drops below 1.
contract SolvencyPriceGeq1 {

    /// @dev mulDiv floor: (a * b) / c, rounding down.
    ///      We keep it simple for the solver: a * b must not overflow uint256.
    function mulDivDown(uint256 a, uint256 b, uint256 c) internal pure returns (uint256) {
        require(c > 0);
        return (a * b) / c;
    }

    /// @notice Stateless check: starting from a valid vault state (A >= S, S > 0),
    ///         after one deposit with a fee, the new state still satisfies A' >= S'.
    function check_solvency_after_deposit(
        uint256 totalAssets,   // pre-state assets
        uint256 totalShares,   // pre-state shares
        uint256 depositAmount, // raw deposit
        uint256 feeBps         // fee in basis points [0, 10000)
    ) external pure {
        // --- Preconditions (sound assumes) ---
        // Vault is non-empty with price >= 1
        require(totalShares > 0);
        require(totalAssets >= totalShares);

        // Deposit is positive and bounded to avoid overflow
        require(depositAmount > 0);
        require(depositAmount <= 1e30);
        require(totalAssets <= 1e30);
        require(totalShares <= 1e30);

        // Fee is < 100 %
        require(feeBps < 10000);

        // --- Fee calculation ---
        uint256 fee = mulDivDown(depositAmount, feeBps, 10000);
        uint256 netDeposit = depositAmount - fee;
        // netDeposit >= 0 always since fee = floor(depositAmount * feeBps / 10000)
        //   and feeBps < 10000  ⟹  fee < depositAmount

        // --- Share minting (round DOWN — favors vault) ---
        uint256 sharesToMint = mulDivDown(netDeposit, totalShares, totalAssets);

        // --- Post-state ---
        uint256 newAssets = totalAssets + depositAmount;   // ALL assets deposited go in (fee stays as assets)
        uint256 newShares = totalShares + sharesToMint;

        // --- Invariant: price >= 1  ⟺  newAssets >= newShares ---
        assert(newAssets >= newShares);
    }

    /// @notice Also check the trivial initial-deposit path (first depositor).
    function check_solvency_initial_deposit(
        uint256 depositAmount,
        uint256 feeBps
    ) external pure {
        require(depositAmount > 0);
        require(depositAmount <= 1e30);
        require(feeBps < 10000);

        // Initial deposit: 1:1 share minting on the net amount
        uint256 fee = mulDivDown(depositAmount, feeBps, 10000);
        uint256 netDeposit = depositAmount - fee;
        require(netDeposit > 0);

        uint256 newAssets = depositAmount;   // full amount as assets
        uint256 newShares = netDeposit;       // shares = net (1:1 bootstrap)

        assert(newAssets >= newShares);
    }
}

