// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/// @title Solvency harness: totalAssets >= totalShares under fee + rounding
contract SolvencyPriceGeq1 {

    /// @notice Stateless check: starting from a valid vault state (A >= S, S > 0),
    ///         after one deposit with a fee, the new state still satisfies A' >= S'.
    function check_solvency_after_deposit(
        uint256 totalAssets,
        uint256 totalShares,
        uint256 depositAmount,
        uint256 feeBps
    ) external pure {
        // --- Preconditions ---
        require(totalShares > 0);
        require(totalAssets >= totalShares);
        require(depositAmount > 0);
        require(depositAmount <= 1e30);
        require(totalAssets <= 1e30);
        require(totalShares <= 1e30);
        require(feeBps < 10000);

        // --- Fee (floor division) ---
        uint256 fee = (depositAmount * feeBps) / 10000;
        uint256 netDeposit = depositAmount - fee;

        // --- Share minting (floor division — favors vault) ---
        uint256 sharesToMint = (netDeposit * totalShares) / totalAssets;

        // Guide solver: floor(x * (S/A)) <= x  when S <= A
        // Since totalShares <= totalAssets:
        //   netDeposit * totalShares <= netDeposit * totalAssets
        //   so floor(netDeposit * totalShares / totalAssets) <= netDeposit
        assert(sharesToMint <= netDeposit);

        // And netDeposit <= depositAmount (fee >= 0)
        assert(sharesToMint <= depositAmount);

        // --- Post-state ---
        uint256 newAssets = totalAssets + depositAmount;
        uint256 newShares = totalShares + sharesToMint;

        // newAssets = totalAssets + depositAmount
        //          >= totalShares + sharesToMint    (since totalAssets >= totalShares and depositAmount >= sharesToMint)
        //          = newShares
        assert(newAssets >= newShares);
    }

    /// @notice Initial deposit path.
    function check_solvency_initial_deposit(
        uint256 depositAmount,
        uint256 feeBps
    ) external pure {
        require(depositAmount > 0);
        require(depositAmount <= 1e30);
        require(feeBps < 10000);

        uint256 fee = (depositAmount * feeBps) / 10000;
        uint256 netDeposit = depositAmount - fee;
        require(netDeposit > 0);

        uint256 newAssets = depositAmount;
        uint256 newShares = netDeposit;

        assert(newAssets >= newShares);
    }
}

